// Portfolio data — Marcello Ronchetti, fotografo di sport e motorsport.

export type Route =
  | 'cover'
  | 'gallery'
  | 'story'
  | 'videos'
  | 'contact'

// Semantic navigation target used by the views; App maps it onto router paths.
export type GoFn = (next: Route, ref?: string, tag?: string) => void

// URL slug for a category: lowercase, percent-encoded (matches the prerendered
// /gallery/<slug>/ paths generated by scripts/generate-seo-assets.mjs).
export const slugOf = (category: string) => encodeURIComponent(category.toLowerCase())

